# Template formula. The authoritative formula is generated by GoReleaser
# (see .goreleaser.yml) and published to thebuildlabs/homebrew-tap on release.
# Replace SHA256 placeholders below only when cutting a manual release.
class Calendarctl < Formula
  desc "Modern calendar management for the terminal"
  homepage "https://github.com/thebuildlabs/calendarctl"
  version "0.1.0"
  license "MIT"
  head "https://github.com/thebuildlabs/calendarctl.git", branch: "main"

  on_macos do
    on_arm do
      url "https://github.com/thebuildlabs/calendarctl/releases/download/v#{version}/calendarctl_#{version}_Darwin_arm64.tar.gz"
      sha256 "REPLACE_WITH_ARM64_SHA256"
    end
    on_intel do
      url "https://github.com/thebuildlabs/calendarctl/releases/download/v#{version}/calendarctl_#{version}_Darwin_x86_64.tar.gz"
      sha256 "REPLACE_WITH_X86_64_SHA256"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/thebuildlabs/calendarctl/releases/download/v#{version}/calendarctl_#{version}_Linux_x86_64.tar.gz"
      sha256 "REPLACE_WITH_LINUX_SHA256"
    end
  end

  def install
    bin.install "calendarctl"
    if OS.mac?
      bin.install "EventKitBridge"
      bin.install "EventKitBridge.app"
    end
  end

  test do
    assert_match "calendarctl", shell_output("#{bin}/calendarctl version")
  end
end
